/**
 * @param {number[]} nums
 * @return {number}
 */
var repeatedNTimes = function(nums) {
    const n = nums.length / 2;
    const map = new Map();

    for (const num of nums) {
        const count = map.get(num) || 0;

        if (count === n - 1) {
            return num;
        }

        map.set(num, count + 1);
    }

    return -1;
};
